const body = $input.item.json.body || $input.item.json;
const task_pl = body.task_pl || '';
const context = body.context || '';
const expected_intent = body.expected_intent || '';
const user_text = (body.user_text || '').slice(0, 500);
const level = body.level || 1;

const system = `You are a friendly English coach for a Polish A1-A2 event-tech project manager (LED screens, rigging, trade fair stands). Judge whether the learner's message would work in a real conversation with a client at a trade fair. Be strict on meaning (does it actually answer the task?), lenient on grammar (small mistakes are fine if understandable). Reply with ONLY a single JSON object, no markdown, no code fences, matching exactly this shape: {\"ok\":true,\"score\":0-100,\"corrected\":\"the learner's sentence, lightly corrected\",\"natural\":\"how a native speaker would naturally say it in this situation\",\"tip_pl\":\"one short tip in Polish\",\"new_chunk\":\"optional: one extra useful short phrase for this situation, or empty string\"}. Never include anything outside the JSON object.`;

const userMessage = `Task (in Polish, what the learner was asked to do): ${task_pl}\nContext: ${context}\nExpected intent: ${expected_intent}\nLearner level: A${level <= 5 ? '1' : '2'}\nLearner's message: "${user_text}"`;

return [{ json: { system, userMessage, task_pl, user_text } }];

let out;
try {
  const text = $input.item.json.content?.[0]?.text || '{}';
  const cleaned = text.trim().replace(/^```json\n?/, '').replace(/```$/, '');
  const parsed = JSON.parse(cleaned);
  out = {
    ok: true,
    score: Math.max(0, Math.min(100, Number(parsed.score) || 0)),
    corrected: String(parsed.corrected || ''),
    natural: String(parsed.natural || ''),
    tip_pl: String(parsed.tip_pl || ''),
    new_chunk: parsed.new_chunk ? String(parsed.new_chunk) : undefined,
  };
} catch (e) {
  out = { ok: false, score: 0, corrected: '', natural: '', tip_pl: 'Błąd po stronie AI, spróbuj ponownie.' };
}
return [{ json: out }];
